function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'CountIntervals' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with CountIntervals() and no arguments.';
  if (operations.length - 1 > 100000) return 'At most 10^5 calls to add and count.';
  let counted = false;
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (!Array.isArray(a)) return 'Each call needs a list of arguments.';
    if (operations[i] === 'add') {
      if (a.length !== 2 || !Number.isInteger(a[0]) || !Number.isInteger(a[1])) return 'add takes two whole numbers.';
      if (a[0] < 1 || a[0] > a[1] || a[1] > 1000000000) return 'add needs 1 <= left <= right <= 10^9.';
    } else if (operations[i] === 'count') {
      if (a.length !== 0) return 'count takes no arguments.';
      counted = true;
    } else {
      return 'Only add and count can follow the constructor.';
    }
  }
  if (!counted) return 'Call count at least once.';
  return null;
}

