class CountIntervals {
  constructor() {
    this.added = [];
  }
  add(left, right) {
    this.added.push([left, right]);
  }
  count() {
    const sorted = this.added.slice().sort((a, b) => a[0] - b[0]);
    let covered = 0;
    let reach = 0;
    for (const [left, right] of sorted) {
      const from = Math.max(left, reach + 1);
      if (right >= from) covered += right - from + 1;
      reach = Math.max(reach, right);
    }
    return covered;
  }
}

