function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const calls = large ? 499 : int(1, 14);
  const limit = large ? (rand() < 0.5 ? 1000000000 : int(1000, 100000)) : (rand() < 0.5 ? 12 : 40);
  const countRate = 0.15 + rand() * 0.4;
  const operations = ['CountIntervals'];
  const args = [[]];
  let counted = false;
  for (let c = 0; c < calls; c++) {
    if (c === calls - 1 && !counted || rand() < countRate) {
      operations.push('count');
      args.push([]);
      counted = true;
    } else {
      const shape = rand();
      const width = shape < 0.4 ? int(0, 3) : shape < (large ? 0.98 : 0.8) ? int(0, Math.max(1, Math.floor(limit / (large ? 400 : 20)))) : int(0, limit - 1);
      const left = int(1, limit - width);
      operations.push('add');
      args.push([left, left + width]);
    }
  }
  return [operations, args];
}
